CREATE TABLE IF NOT EXISTS users(id SERIAL PRIMARY KEY,name VARCHAR(120) NOT NULL,email VARCHAR(180) NOT NULL UNIQUE,password_hash TEXT NOT NULL,phone VARCHAR(30) DEFAULT '',address TEXT DEFAULT '',role VARCHAR(20) NOT NULL DEFAULT 'customer' CHECK(role IN ('customer','admin')),active BOOLEAN NOT NULL DEFAULT true,created_at TIMESTAMPTZ NOT NULL DEFAULT NOW());
CREATE TABLE IF NOT EXISTS categories(id SERIAL PRIMARY KEY,name VARCHAR(100) NOT NULL UNIQUE);
CREATE TABLE IF NOT EXISTS products(id SERIAL PRIMARY KEY,name VARCHAR(180) NOT NULL,description TEXT DEFAULT '',price NUMERIC(12,2) NOT NULL CHECK(price>=0),stock INTEGER NOT NULL DEFAULT 0 CHECK(stock>=0),category_id INTEGER REFERENCES categories(id) ON DELETE RESTRICT,image_url TEXT,active BOOLEAN NOT NULL DEFAULT true,created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW());
CREATE TABLE IF NOT EXISTS cart_items(id SERIAL PRIMARY KEY,user_id INTEGER NOT NULL REFERENCES users(id) ON DELETE CASCADE,product_id INTEGER NOT NULL REFERENCES products(id) ON DELETE CASCADE,quantity INTEGER NOT NULL CHECK(quantity>0),UNIQUE(user_id,product_id));
CREATE TABLE IF NOT EXISTS orders(id SERIAL PRIMARY KEY,user_id INTEGER NOT NULL REFERENCES users(id),total NUMERIC(12,2) NOT NULL,address TEXT NOT NULL,payment_method VARCHAR(20) NOT NULL CHECK(payment_method IN('COD','UPI')),payment_status VARCHAR(20) NOT NULL DEFAULT 'Pending' CHECK(payment_status IN('Pending','Paid')),status VARCHAR(20) NOT NULL DEFAULT 'Pending' CHECK(status IN('Pending','Confirmed','Shipped','Delivered','Cancelled')),created_at TIMESTAMPTZ NOT NULL DEFAULT NOW());
CREATE TABLE IF NOT EXISTS order_items(id SERIAL PRIMARY KEY,order_id INTEGER NOT NULL REFERENCES orders(id) ON DELETE CASCADE,product_id INTEGER REFERENCES products(id) ON DELETE SET NULL,product_name VARCHAR(180) NOT NULL,unit_price NUMERIC(12,2) NOT NULL,quantity INTEGER NOT NULL,subtotal NUMERIC(12,2) NOT NULL);
CREATE TABLE IF NOT EXISTS messages(id SERIAL PRIMARY KEY,name VARCHAR(120) NOT NULL,email VARCHAR(180) NOT NULL,subject VARCHAR(180) DEFAULT '',message TEXT NOT NULL,created_at TIMESTAMPTZ NOT NULL DEFAULT NOW());
CREATE INDEX IF NOT EXISTS idx_orders_user ON orders(user_id);CREATE INDEX IF NOT EXISTS idx_products_category ON products(category_id);CREATE INDEX IF NOT EXISTS idx_cart_user ON cart_items(user_id);
